/**
 * Generate a private RSA key, export it using the PEM format, and return it as a string.
 *
 *
 * @returns {string} The RSA private key in PEM format.
 */
function create_private_key() {
  // Generate a new RSA private key.
  // For enhanced security, a passphrase should be used.
  // However, to strictly adhere to the requirement of returning the key as a string
  // without external dependencies for passphrase management in this example,
  // we will generate a key without a passphrase.
  // In a production environment, it is highly recommended to use a passphrase
  // and manage it securely (e.g., via environment variables or a secrets manager).
  const {
    privateKey
  } = crypto.generateKeyPairSync('rsa', {
    modulusLength: 2048, // Key size in bits
    publicKeyEncoding: {
      type: 'spki', // SubjectPublicKeyInfo
      format: 'pem'
    },
    privateKeyEncoding: {
      type: 'pkcs8', // PKCS#8 format
      format: 'pem',
